script:
# New York's laws from the Senate's Open Legislation API (docs:
# legislation.nysenate.gov/static/docs/html/index.html; a free key, SCOUT_KEY_NYSENATE). Every law volume (137: consolidated, unconsolidated, court acts,
# rules, misc) in one call each with full text; a volume too big for one call is read article by article. Each section
# names its own law as its document. Citations use the usual short forms (CPLR, SCPA, FCA ...), else the API's lawId.
import re

API = "https://legislation.nysenate.gov/api/3/laws"
ABBR = {"CVP": "CPLR", "SCP": "SCPA", "FCT": "FCA", "DOM": "DRL", "CPL": "CPL", "MHY": "MHL", "RPA": "RPAPL",
        "PEN": "Penal Law", "VAT": "VTL", "SOS": "SSL"}
NUM = re.compile(r"\s*(?:§+|Rule|Sec(?:tion)?\.?)\s*([0-9][0-9A-Za-z.\-]*[0-9A-Za-z])\.?[ \t]*(.*)", re.S)


def _walk(d):
    yield d
    for c in (d.get("documents") or {}).get("items") or []:
        yield from _walk(c)


def _heading(rest):
    """The first line and its deep-indented continuations, cut at the first sentence end."""
    lines = rest.split("\n")
    head = [lines[0]]
    for ln in lines[1:]:
        if re.match(r" {5,}\S", ln) or re.match(r"\s*[a-z]", ln):     # deep indent, or a wrapped line going on in lower case
            head.append(ln.strip())
        else:
            break
    h = " ".join(" ".join(head).split())
    return re.split(r"(?<=[a-z0-9)\]\"'”’])\.(?:\s|$)", h, 1)[0].strip()[:300]      # also after a closing quote: Definition of "x".


def _parts(law_id):
    try:
        return [fetch_json(f"{API}/{law_id}?full=true")["result"]["documents"]]
    except Exception as e:  # noqa: BLE001
        log(f"{law_id}: the whole volume in one call failed ({str(e)[:80]}); reading it part by part")
    tree = fetch_json(f"{API}/{law_id}")["result"]["documents"]
    out = []
    for top in (tree.get("documents") or {}).get("items") or []:
        try:
            out.append(fetch_json(f"{API}/{law_id}/{top['locationId']}?full=true")["result"])
        except Exception as e:  # noqa: BLE001
            log(f"{law_id}/{top['locationId']}: not read ({str(e)[:80]})")
    return out


def sections():
    laws = fetch_json(f"{API}?limit=1000")["result"]["items"]
    log(f"{len(laws)} law volumes listed")
    for law in laws:
        lid, name = law["lawId"], (law.get("name") or law["lawId"]).strip()
        abbr = ABBR.get(lid, lid)
        doc = {"citation": f"N.Y. {abbr}", "title": f"{name} ({lid})", "doc_type": "statute", "source_url": f"{API}/{lid}"}
        n = 0
        for part in _parts(lid):
            for d in _walk(part):
                if d.get("docType") != "SECTION" or not d.get("text"):
                    continue
                text = d["text"].replace("\\n", "\n").strip("\n")
                m = NUM.match(text)
                num = m.group(1) if m else re.sub(r"^R(?=\d)", "", d["locationId"]).lower()
                n += 1
                yield {"id": num, "vars": {"code": abbr}, "heading": _heading(m.group(2)) if m else str(d.get("title") or "")[:300],
                       "text": text.strip(), "doc": doc, "url": f"{API}/{lid}/{d['locationId']}"}
        log(f"{lid} ({name}): {n} sections")
